CREATE OR REPLACE FUNCTION public.seed_demo_attendance_chunk(p_school uuid, p_from date, p_to date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Not authorised'; END IF; INSERT INTO public.attendance_records (school_id,student_id,class_id,date,status) SELECT p_school,s.id,s.class_id,d::date, CASE WHEN random()<0.9 THEN 'present'::public.attendance_status WHEN random()<0.5 THEN 'absent'::public.attendance_status WHEN random()<0.6 THEN 'late'::public.attendance_status ELSE 'excused'::public.attendance_status END FROM public.students s CROSS JOIN generate_series(p_from,p_to,interval '1 day') d WHERE s.school_id=p_school AND extract(dow FROM d) BETWEEN 1 AND 5 ON CONFLICT (student_id,date) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.seed_demo_attendance_chunk(uuid,date,date) FROM PUBLIC;
