CREATE OR REPLACE FUNCTION public.seed_demo_marks_chunk(p_school uuid,p_from integer,p_to integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Not authorised'; END IF; INSERT INTO public.marks (school_id,assessment_id,student_id,score) SELECT p_school,a.id,s.id,round((35+random()*63)::numeric,1) FROM (SELECT id,class_id FROM public.assessments WHERE school_id=p_school AND class_id IN (SELECT id FROM (SELECT id,row_number() OVER (ORDER BY id) rn FROM public.classes WHERE school_id=p_school) numbered WHERE rn BETWEEN p_from AND p_to)) a JOIN public.students s ON s.class_id=a.class_id AND s.school_id=p_school ON CONFLICT (assessment_id,student_id) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.seed_demo_marks_chunk(uuid,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.seed_demo_marks_chunk(uuid,integer,integer) TO service_role;